    api,
    event,
	helpers,
}) {
    const automationText = helpers.translateSync('Are subject to automation.');
    const qualityText = helpers.translateSync('Reveals unnecessary process steps.');
    const conformanceText = helpers.translateSync('Checks if the actual execution of the process, as recorded in the event log, conforms to the desired / designed model and vice versa.');
    const performanceText = helpers.translateSync('Checks the speed of the actual execution of the process.');

    const categoriesInfo = {
        AUTOMATION: automationText,
        QUALITY: qualityText,
        CONFORMANCE: conformanceText,
        PERFORMANCE: performanceText,
    };

    return {
        propName: 'infoPopoverText',
        value: categoriesInfo[api.state.automatedFindingForm.category.selectedValue],
    };
}

