function evaluateEvent({
    api,
    event
}) {
    const findingConfigurationMap = { ...api.state.findingConfigurationMap
    };
    const reg = new RegExp('^[0-9]+$');
    if (reg.test(event.payload.fieldValue.trim()) == false) {
        findingConfigurationMap.durationMultiplier.invalid = true;
    } else if (Number(event.payload.fieldValue) < 10) {
        findingConfigurationMap.durationMultiplier.invalid = true;
    } else {
        findingConfigurationMap.durationMultiplier.invalid = false;
    }
    findingConfigurationMap.durationMultiplier.value = event.payload.fieldValue;

    return {
        propName: 'findingConfigurationMap',
        value: findingConfigurationMap
    };
})

