        findingConfigurationMap.minTotalDurationMinutes.invalid = false;
         if (event.payload.fieldValue < 120) {
           findingConfigurationMap.minTotalDurationMinutes.invalid = true; 
        }
    }
    findingConfigurationMap.minTotalDurationMinutes.value = event.payload.fieldValue;

    return {
        propName: 'findingConfigurationMap',
        value: findingConfigurationMap
    };
})

